#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-12

# Test: scripts/traffic-snapshot.mjs writes exactly one JSONL row for the
# measured week and FAILS CLOSED: when any GitHub traffic endpoint read fails,
# nothing is written and the exit is non-zero (#4071).
#
# Why: .github/workflows/traffic-snapshot.yml commits the row to
# docs/traffic/snapshots.jsonl and opens a PR with it. A partial read that
# still produced a row would commit a traffic collapse that never happened,
# and a write-before-validate would leave a half row behind when a later
# endpoint 500s. The paired control/fault arms below pin the fail-closed
# behavior the same way tests/ci/test-audit-skill-claims-blind-sweep.sh pins
# its gate.
#
# Arms (clock pinned with --now 2026-09-14T06:00:00Z, so the measured week is
# always [2026-09-07, 2026-09-14) UTC):
#   control:       all four endpoints answer with 7 in-window day buckets
#                  -> exit 0, one row, exact window sums, GITHUB_OUTPUT
#                  row=written + week=2026-09-07
#   idempotency:   same week again -> exit 0, row=skipped, file byte-identical
#   fault views:   views endpoint fails (HTTP 500) -> exit non-zero, NO file
#   fault clones:  clones endpoint answers 200 with a non-JSON body
#                  -> exit non-zero, NO file
#   fault paths:   popular paths endpoint fails -> exit non-zero, NO file
#   fault types:   views .count is a string, not a number -> exit non-zero, NO file
#   fault window:  every views bucket sits outside the measured week
#                  -> exit non-zero, NO file (never a zero row)

set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
SNAPSHOT_SCRIPT="$REPO_ROOT/scripts/traffic-snapshot.mjs"

echo "=== traffic-snapshot fail-closed gate ==="
echo ""

WORK="$(mktemp -d "${TMPDIR:-/tmp}/ork-traffic-snapshot.XXXXXX")"
trap 'rm -rf "$WORK"' EXIT

PASS=0
FAIL=0
ok()  { echo "  PASS: $1"; PASS=$((PASS + 1)); }
bad() { echo "  FAIL: $1"; FAIL=$((FAIL + 1)); }

# --- gh stub: serves fixture files as gh api responses ------------------------
# `gh api <endpoint>` maps to a fixture file per endpoint, overridable with
# TRAFFIC_STUB_<KEY>_FILE; TRAFFIC_STUB_FAIL_<KEY>=1 makes the endpoint die
# the way a real gh does on an HTTP error (message on stderr, exit 1).
STUB_BIN="$WORK/bin"
FX="$WORK/fx"
mkdir -p "$STUB_BIN" "$FX"
# pipebuf: bounded-literal. The 706B heredoc body is redirected straight to a
# regular file (no pipe reader involved), and its size is fixed by this file.
cat > "$STUB_BIN/gh" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
endpoint="${2:-}"
key=""
case "$endpoint" in
  */traffic/views)             key="VIEWS" ;;
  */traffic/clones)            key="CLONES" ;;
  */traffic/popular/paths)     key="PATHS" ;;
  */traffic/popular/referrers) key="REFERRERS" ;;
  *) echo "gh stub: unexpected endpoint: $endpoint" >&2; exit 64 ;;
esac
failvar="TRAFFIC_STUB_FAIL_${key}"
if [[ "${!failvar:-}" == "1" ]]; then
  echo "gh: HTTP 500: stubbed failure for ${key}" >&2
  exit 1
fi
fx="${TRAFFIC_FIXTURES:?TRAFFIC_FIXTURES must point at the fixture directory}"
filevar="TRAFFIC_STUB_${key}_FILE"
default_file="$(printf '%s' "$key" | tr '[:upper:]' '[:lower:]').json"
cat "$fx/${!filevar:-$default_file}"
EOF
chmod +x "$STUB_BIN/gh"

# --- fixtures ------------------------------------------------------------------
# Views: 14 daily buckets, 2026-08-31 .. 2026-09-13. Counts 5..18, uniques
# 3..16. The measured week keeps the last 7 buckets: counts 12..18 (sum 105),
# uniques 10..16 (sum 91). GitHub's own top-level count covers the whole
# 14-day span (161/133), so window sums differing from top-level values is
# itself part of the assertion.
V14_DATES=("2026-08-31" "2026-09-01" "2026-09-02" "2026-09-03" "2026-09-04" "2026-09-05" "2026-09-06" "2026-09-07" "2026-09-08" "2026-09-09" "2026-09-10" "2026-09-11" "2026-09-12" "2026-09-13")
OLD14_DATES=("2026-08-17" "2026-08-18" "2026-08-19" "2026-08-20" "2026-08-21" "2026-08-22" "2026-08-23" "2026-08-24" "2026-08-25" "2026-08-26" "2026-08-27" "2026-08-28" "2026-08-29" "2026-08-30")

write_daily_fixture() { # <file> <dates...> ; counts 5..18, uniques 3..16
  local file="$1"
  shift
  local out='{"count":161,"uniques":133,"daily":['
  local first=1
  local i=0
  local d
  for d in "$@"; do
    [ "$first" -eq 1 ] || out="$out,"
    first=0
    out="$out{\"timestamp\":\"${d}T00:00:00Z\",\"count\":$((5 + i)),\"uniques\":$((3 + i))}"
    i=$((i + 1))
  done
  out="$out]}"
  # The array key differs per endpoint; the base fixture uses "daily" and the
  # caller below renames the key with jq to match the real API shape.
  printf '%s\n' "$out" > "$file"
}

# views.json (happy): array key "views"
write_daily_fixture "$FX/views-base.json" "${V14_DATES[@]}"
jq '.daily as $d | {count, uniques, views: $d}' "$FX/views-base.json" > "$FX/views.json"
# clones.json (happy): counts 1..14, uniques 0..13, top-level 105/91,
# array key "clones"
write_daily_fixture "$FX/clones-base.json" "${V14_DATES[@]}"
jq '.daily as $d |
    {count: 105, uniques: 91,
     clones: [$d[] | .count = (.count - 4) | .uniques = (.uniques - 3)]}' \
  "$FX/clones-base.json" > "$FX/clones.json"
# popular paths / referrers (happy): note the null title in item 2
cat > "$FX/paths.json" <<'EOF'
[
  {"path": "/yonatangross/orchestkit", "title": "OrchestKit", "count": 40, "uniques": 25},
  {"path": "/yonatangross/orchestkit/blob/main/README.md", "title": null, "count": 12, "uniques": 8}
]
EOF
cat > "$FX/referrers.json" <<'EOF'
[
  {"referrer": "google.com", "count": 30, "uniques": 22},
  {"referrer": "duckduckgo.com", "count": 6, "uniques": 5}
]
EOF
# fault fixtures
printf 'not json at all\n' > "$FX/clones-garbage.json"
# bad types: .count is a string; buckets valid and in-window
jq '{count: "161", uniques, views: .views}' "$FX/views.json" > "$FX/views-bad-types.json"
# empty window: all buckets in the PREVIOUS week (2026-08-17 .. 2026-08-30),
# so the measured week has zero buckets and the run must refuse to write
write_daily_fixture "$FX/views-empty-window-base.json" "${OLD14_DATES[@]}"
jq '.daily as $d | {count, uniques, views: $d}' "$FX/views-empty-window-base.json" > "$FX/views-empty-window.json"

# --- runner --------------------------------------------------------------------
# run_traffic <stdout> <stderr> <gh-output> <out-jsonl> [KEY=VALUE ...]
# Sets RC. Clock is pinned so the measured week is [2026-09-07, 2026-09-14).
run_traffic() {
  local stdout_f="$1" stderr_f="$2" ghout="$3" out="$4"
  shift 4
  set +e
  env "$@" PATH="$STUB_BIN:$PATH" TRAFFIC_FIXTURES="$FX" GITHUB_OUTPUT="$ghout" \
    node "$SNAPSHOT_SCRIPT" --repo yonatangross/orchestkit --out "$out" --now 2026-09-14T06:00:00Z \
    > "$stdout_f" 2> "$stderr_f"
  RC=$?
  set -e
}

# --- control: happy path ---------------------------------------------------------
OUT="$WORK/control/snapshots.jsonl"
GHOUT="$WORK/control/ghout"
mkdir -p "$WORK/control"
run_traffic "$WORK/control/stdout" "$WORK/control/stderr" "$GHOUT" "$OUT"

if [ "$RC" -eq 0 ]; then ok "control: exit 0"; else bad "control: exit $RC (expected 0); stderr: $(cat "$WORK/control/stderr")"; fi
if [ -f "$OUT" ]; then ok "control: row file written"; else bad "control: row file missing"; fi
if [ "$(wc -l < "$OUT")" -eq 1 ]; then ok "control: exactly one JSONL row"; else bad "control: expected 1 line, got $(wc -l < "$OUT")"; fi
if jq -e '.week == "2026-09-07"' "$OUT" > /dev/null; then ok "control: week key is 2026-09-07"; else bad "control: week key wrong: $(cat "$OUT")"; fi
if jq -e '.views.total == 105 and .views.uniques == 91' "$OUT" > /dev/null; then ok "control: views window sums 105/91"; else bad "control: views sums wrong: $(jq '.views' "$OUT")"; fi
if jq -e '.views.days_observed == 7 and (.views.days | length) == 7' "$OUT" > /dev/null; then ok "control: 7 days observed"; else bad "control: days_observed wrong"; fi
if jq -e '.views.days[0].date == "2026-09-07" and .views.days[-1].date == "2026-09-13"' "$OUT" > /dev/null; then ok "control: day buckets span the measured week"; else bad "control: day span wrong"; fi
if jq -e '.clones.total == 77 and .clones.uniques == 70' "$OUT" > /dev/null; then ok "control: clones window sums 77/70"; else bad "control: clones sums wrong: $(jq '.clones' "$OUT")"; fi
if jq -e '.popular_paths.items | length == 2' "$OUT" > /dev/null; then ok "control: 2 popular paths"; else bad "control: popular paths wrong"; fi
if jq -e '.popular_paths.items[1].title == ""' "$OUT" > /dev/null; then ok "control: null title normalized to empty string"; else bad "control: null title not normalized"; fi
if jq -e '.referrers.items | length == 2' "$OUT" > /dev/null; then ok "control: 2 referrers"; else bad "control: referrers wrong"; fi
if jq -e '.generated_at == "2026-09-14T06:00:00.000Z"' "$OUT" > /dev/null; then ok "control: generated_at pinned to the clock"; else bad "control: generated_at wrong: $(jq -r '.generated_at' "$OUT")"; fi
if grep -q '^row=written$' "$GHOUT" && grep -q '^week=2026-09-07$' "$GHOUT"; then ok "control: GITHUB_OUTPUT row=written + week"; else bad "control: GITHUB_OUTPUT wrong: $(cat "$GHOUT" 2>/dev/null)"; fi

cp "$OUT" "$WORK/control/first-row.jsonl"
run_traffic "$WORK/control/stdout2" "$WORK/control/stderr2" "$WORK/control/ghout2" "$OUT"
if [ "$RC" -eq 0 ]; then ok "idempotency: second run exits 0"; else bad "idempotency: second run exit $RC"; fi
if grep -q '^row=skipped$' "$WORK/control/ghout2"; then ok "idempotency: GITHUB_OUTPUT row=skipped"; else bad "idempotency: ghout2 wrong: $(cat "$WORK/control/ghout2" 2>/dev/null)"; fi
if cmp -s "$WORK/control/first-row.jsonl" "$OUT"; then ok "idempotency: file byte-identical after skip"; else bad "idempotency: file changed on skip"; fi
if [ "$(wc -l < "$OUT")" -eq 1 ]; then ok "idempotency: still exactly one row"; else bad "idempotency: duplicate row appended"; fi

# --- fault arms: every one must exit non-zero and write NOTHING ------------------
FAULT_CASES=(
  "views http failure|TRAFFIC_STUB_FAIL_VIEWS=1"
  "clones garbage body|TRAFFIC_STUB_CLONES_FILE=clones-garbage.json"
  "popular paths failure|TRAFFIC_STUB_FAIL_PATHS=1"
  "views count not a number|TRAFFIC_STUB_VIEWS_FILE=views-bad-types.json"
  "empty measured week|TRAFFIC_STUB_VIEWS_FILE=views-empty-window.json"
)
for case_def in "${FAULT_CASES[@]}"; do
  label="${case_def%%|*}"
  env_pair="${case_def#*|}"
  fdir="$WORK/fault-$(printf '%s' "$label" | tr ' ' '-')"
  mkdir -p "$fdir"
  run_traffic "$fdir/stdout" "$fdir/stderr" "$fdir/ghout" "$fdir/snapshots.jsonl" "$env_pair"
  if [ "$RC" -ne 0 ]; then
    ok "fault [$label]: exit non-zero ($RC)"
  else
    bad "fault [$label]: exited 0, fail-closed breached; stderr: $(cat "$fdir/stderr")"
  fi
  if [ ! -e "$fdir/snapshots.jsonl" ]; then
    ok "fault [$label]: nothing written"
  else
    bad "fault [$label]: file was written despite failure: $(cat "$fdir/snapshots.jsonl")"
  fi
done

echo ""
if [ "$FAIL" -gt 0 ]; then
  echo "traffic-snapshot test: $FAIL failing assertion(s), $PASS passing"
  exit 1
fi
echo "traffic-snapshot test: all $PASS assertions passed"
